from pathlib import Path
from PIL import Image,ImageDraw,ImageFont,ImageOps
import json,html
r=Path(__file__).resolve().parent
results=json.loads((r/'results.json').read_text())
review=r/'revisao';review.mkdir(exist_ok=True)
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',20)
for seq in results['sequences']:
    frames=seq['frames']; selected=[frames[round(i*(len(frames)-1)/8)] for i in range(9)]
    sheet=Image.new('RGB',(1440,1020),'#fbf6e9');d=ImageDraw.Draw(sheet)
    d.text((15,10),seq['name']+' / amostras reais, nao benchmark FPS',font=font,fill='#292074')
    for i,f in enumerate(selected):
        im=Image.open(r/'sequencias'/seq['name']/f['file']);im=ImageOps.contain(im,(470,285))
        x=(i%3)*480+5;y=(i//3)*320+50
        sheet.paste(im,(x,y));d.text((x,y+285),f"t={f['time']:.2f}s / camada {f['z']}",font=font,fill='#292074')
    sheet.save(review/(seq['name']+'-folha.jpg'),quality=88)
data={'pairs':[],'sequences':results['sequences']}
for a in results['comparisons']:
    if a['version']!='p2':continue
    w=a['viewport'][0];p=a['product'];phase=a['phase']
    data['pairs'].append({'label':f'{w}px / produto {p+1} / {phase}','p2':f'../capturas/p2-{w}-product{p}-{phase}.png','p3':f'../capturas/p3-{w}-product{p}-{phase}.png','time':a['state']['orbitTime']})
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Revisão local P3-D H01</title><style>body{font:16px system-ui;background:#fbf6e9;color:#292074;margin:24px}button,select{font:inherit;padding:10px;margin:5px}img{max-width:100%;height:auto}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pair img{width:100%}.frame{max-height:75vh;display:block}h2{margin-top:35px}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style><h1>P3-D / H01-v02 / integração experimental local</h1><p>Sem autorização de publicação ou aprovação definitiva da fidelidade comercial. Comparações abaixo usam a mesma fase forçada somente pelo teste; o código do site mantém a órbita P2.</p><h2>P2 × P3 na mesma fase</h2><select id="pair"></select><p id="phase"></p><div class="pair"><div><strong>P2 / doce CSS</strong><img id="before"></div><div><strong>P3 / H01-v02</strong><img id="after"></div></div><h2>Sequências reais de uma órbita completa de H01</h2><p>A captura é amostral. Os intervalos são os valores observados de orbitTime; não comprovam FPS. A reprodução não começa automaticamente.</p><select id="seq"></select><button id="play">Reproduzir</button><button id="prev">Anterior</button><button id="next">Próximo</button><span id="status"></span><img class="frame" id="frame"><p><a href="desktop-minhocas-full-orbit-folha.jpg">Folha desktop Minhocas</a> · <a href="desktop-tubes-full-orbit-folha.jpg">Folha desktop Tubes</a> · <a href="mobile-tubes-full-orbit-folha.jpg">Folha mobile Tubes</a></p><h2>Estados e falhas</h2><p><a href="../capturas/fallback-404.png">HTTP 404</a> · <a href="../capturas/fallback-corrupt.png">Arquivo inválido</a> · <a href="../capturas/fallback-delay.png">Imagem atrasada</a> · <a href="../capturas/delayed-image-ready-reduced.png">Pronta com movimento reduzido</a> · <a href="../capturas/menu-landscape.png">Menu horizontal</a></p><script>const DATA=__DATA__;const pair=document.querySelector('#pair'),seq=document.querySelector('#seq');DATA.pairs.forEach((p,i)=>pair.add(new Option(p.label,i)));function showPair(){const p=DATA.pairs[pair.value];document.querySelector('#before').src=p.p2;document.querySelector('#after').src=p.p3;document.querySelector('#phase').textContent='orbitTime='+p.time.toFixed(6)+'s; mesmos produto, viewport, fase e geometria.'}pair.onchange=showPair;showPair();DATA.sequences.forEach((s,i)=>seq.add(new Option(s.name,i)));let n=0,timer=null;function stop(){clearTimeout(timer);timer=null;document.querySelector('#play').textContent='Reproduzir'}function show(){const s=DATA.sequences[seq.value],f=s.frames[n];document.querySelector('#frame').src='../sequencias/'+s.name+'/'+f.file;document.querySelector('#status').textContent=(n+1)+' / '+s.frames.length+' | órbita '+f.time.toFixed(2)+'s | camada '+f.z}seq.onchange=()=>{stop();n=0;show()};document.querySelector('#next').onclick=()=>{stop();n=(n+1)%DATA.sequences[seq.value].frames.length;show()};document.querySelector('#prev').onclick=()=>{stop();n=(n-1+DATA.sequences[seq.value].frames.length)%DATA.sequences[seq.value].frames.length;show()};document.querySelector('#play').onclick=()=>{if(timer){stop();return}document.querySelector('#play').textContent='Pausar';function step(){const f=DATA.sequences[seq.value].frames,a=n;n=(n+1)%f.length;show();timer=setTimeout(step,n?Math.max(100,(f[n].time-f[a].time)*1000):500)}timer=setTimeout(step,300)};show();</script></html>'''
(review/'index.html').write_text(page.replace('__DATA__',json.dumps(data).replace('</','<\\/')),encoding='utf-8')
print('Visualizador offline e três folhas criados; imagens reais, sem sintetizar frames.')
